async function commitTree(
	dir: string,
	tree: string,
	parents: readonly string[],
	message: string,
): Promise<string> {
	return trim(
		run(dir, ["commit-tree", tree, ...parents.flatMap((p) => ["-p", p])], {
			env: COMMIT_ENV,
			input: message,
		}),
	);
}

